const $ = (s, base = document) => base.querySelector(s);
const $$ = (s, base = document) => [...base.querySelectorAll(s)];
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chainName = chain => chain === 'bnb' ? 'BNB Chain' : 'Solana';
const shortChain = chain => chain === 'bnb' ? 'BNB' : 'SOL';
const chainKeys = ['bnb', 'solana'];
const APP_UI_VERSION = '1.6.0';
const pageNames = {market:'行情首页',settings:'设置与钱包',bridge:'跨链',trades:'交易档案',notes:'备忘录'};
const number = (value, decimals = 2) => value === undefined || value === null || !Number.isFinite(Number(value)) ? '—' : Number(value).toLocaleString('en-US', {minimumFractionDigits:decimals,maximumFractionDigits:decimals});
const usd = (value, decimals = 4) => value === undefined || value === null || !Number.isFinite(Number(value)) ? '—' : '$' + number(value,decimals);
const percent = bps => bps === undefined || bps === null ? '—' : number(Number(bps) / 100,2) + '%';
const time = value => { if(!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : date.toLocaleString('zh-CN',{hour12:false}); };
const clockTime = value => { if(!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : date.toLocaleTimeString('zh-CN',{hour12:false}); };
const short = (value, size = 7) => value ? String(value).length > size * 2 + 3 ? `${String(value).slice(0,size)}…${String(value).slice(-size)}` : String(value) : '未配置';
const numeric = value => Number.isFinite(Number(value)) ? Number(value) : 0;
const icon = name => ({play:'<svg viewBox="0 0 16 16"><path d="m5 3 7 5-7 5z"/></svg>',pause:'<svg viewBox="0 0 16 16"><path d="M5 3v10M11 3v10"/></svg>',refresh:'<svg viewBox="0 0 16 16"><path d="M13 7a5 5 0 1 0-.8 4M13 3v4H9"/></svg>',arrow:'<svg viewBox="0 0 16 16"><path d="M3 8h10m-4-4 4 4-4 4"/></svg>',lock:'<svg viewBox="0 0 16 16"><rect x="3" y="7" width="10" height="7" rx="1"/><path d="M5 7V5a3 3 0 0 1 6 0v2M8 10v2"/></svg>'}[name] ?? '');
let state = null, csrfToken = '', tab = 'market', tradePage = 1, notePage = 1, bridgeQuote = null, bridgeRevision = 0, activeTrade = null, requestBusy = false;
