  radarView.unmount();
  const o = state.opportunity || {}, e = state.engine || {}, risk = state.config.risk || {}, stats = state.stats || {};
  const reasons = o.reasons || ['等待行情与报价'];
  const activeStep = flowStatus(), inventoryMode = state.config.executionMode === 'inventory';
  const usedCount = stats.executions ?? stats.executionCount ?? stats.count ?? 0, usedVolume = stats.cumulativeUsd ?? stats.volumeUsd ?? 0;
  const paused = e.pausedReason;
