  (paused?`<div class="error-box">执行已暂停：${escape(paused)}${(e.reviewTradeId||e.activeTradeId)?`<br>档案编号：<span class="mono">${escape(e.reviewTradeId||e.activeTradeId)}</span>`:''}<div class="form-actions"><button class="button small danger" id="acknowledge">核对后解除暂停</button><button class="button small secondary" data-tab="trades">查看交易档案</button></div></div>`:'')+
  `<div class="chain-grid">${chainCard('bnb')}${chainCard('solana')}</div><section class="card opportunity"><div class="card-header"><h2>套利机会</h2><span class="live-label"><i class="status-dot ${o.executable?'good':'warn'}"></i>${o.executable?'已通过执行检查':'等待执行条件'}</span></div><div class="opportunity-top"><div><div class="direction-label">建议交易方向</div><div class="direction">${o.buyChain?chainPill(o.buyChain):'等待行情'}<em>→</em>${o.sellChain?chainPill(o.sellChain):'—'}</div><div class="direction-detail">${inventoryMode?'低价链买入确认 <span>→</span> 高价链卖出现有库存':'低价链买入 <span>→</span> 跨链到账 <span>→</span> 高价链卖出'}</div></div><div class="key-metric"><div class="label">双链价差</div><div class="value ${numeric(o.spreadBps)>0?'positive':''}">${percent(o.spreadBps)}</div><div class="hint">报价金额 ${usd(o.amountUsd ?? risk.amountUsd,2)}</div></div><div class="key-metric"><div class="label">${inventoryMode?'预计现金流价差':'预计净收益'}</div><div class="value ${numeric(o.netProfitUsd)>=0?'positive':'negative'}">${usd(o.netProfitUsd,4)}</div><div class="hint">利润门槛 ≥ ${usd(risk.minProfitUsd,4)}${inventoryMode?' · 未含补库成本':''}</div></div></div><div class="cost-grid"><div class="cost-item"><div class="stat-label">预计毛收益</div><div class="stat-value">${usd(o.grossProfitUsd)}</div></div><div class="cost-item"><div class="stat-label">滑点成本</div><div class="stat-value">${usd(o.slippageUsd)}</div></div><div class="cost-item"><div class="stat-label">Gas / 网络费</div><div class="stat-value">${usd(o.gasUsd)}</div></div><div class="cost-item"><div class="stat-label">${inventoryMode?'库存调拨':'代币跨链费用'}</div><div class="stat-value">${inventoryMode?'本轮不跨链':usd(o.bridgeFeeUsd)}</div></div><div class="cost-item"><div class="stat-label">价格冲击</div><div class="stat-value">${percent(o.priceImpactBps)}</div></div></div><div class="opportunity-bottom"><div class="block-reasons ${!reasons.length?'ready':''}">${reasons.length?reasons.map(r=>`<div class="reason-line">${escape(r)}</div>`).join(''):'<span>✓ 当前报价已通过利润、费用与余额检查</span>'}${o.expiresAt?`<div class="muted small-text section-gap">报价有效至 ${clockTime(o.expiresAt)}</div>`:''}</div><div class="execution-actions"><button class="button secondary" id="engine-toggle">${icon(e.running?'pause':'play')}${e.running?'暂停自动执行':'启动自动执行'}</button><button class="button" id="execute-arbitrage" ${!o.executable || e.busy || paused?'disabled':''}>${e.busy?'交易执行中':state.config.mode==='demo'?'模拟执行一笔':'执行一笔'}${icon('arrow')}</button></div></div></section><div class="bottom-grid"><section class="card"><div class="card-header"><h3>顺序执行保护</h3><span class="badge neutral">${e.busy?'执行中':'等待任务'}</span></div><div class="flow">${(inventoryMode ? [['01','低价买入','提交交易'],['02','链上确认','核对实际到账'],['03','核对库存','高价链已有同币'],['04','高价卖出','按买入实收换算'],['05','交易复核','记录现金流和库存']] : [['01','低价买入','提交交易'],['02','链上确认','核对实际到账'],['03','代币跨链','等待目标链到账'],['04','高价卖出','使用实收数量'],['05','交易复核','记录实际净收益']]).map(([n,t,s],i)=>`<div class="flow-step ${activeStep===i?'active':activeStep>i?'done':''}"><span class="step-number">${activeStep>i?'✓':n}</span><strong>${t}</strong><small>${s}</small></div>`).join('')}</div><div class="flow-note">${icon('lock')}买入未确认，禁止卖出；单边失败，立即暂停并保留档案。</div></section><section class="card"><div class="card-header"><h3>本轮执行额度</h3><span class="sub">金额限制 ${usd(1,0)}–${usd(10,0)} / 笔</span></div><div class="limit-grid"><div><div class="stat-label">执行次数</div><div class="limit-value">${number(usedCount,0)}<small>/ ${number(risk.maxExecutions,0)} 次</small></div><div class="progress"><i style="width:${Math.min(100,numeric(usedCount)/Math.max(1,numeric(risk.maxExecutions))*100)}%"></i></div></div><div><div class="stat-label">累计执行金额</div><div class="limit-value">${usd(usedVolume,2)}<small>/ ${usd(risk.maxCumulativeUsd,0)}</small></div><div class="progress"><i style="width:${Math.min(100,numeric(usedVolume)/Math.max(1,numeric(risk.maxCumulativeUsd))*100)}%"></i></div></div></div><div class="risk-tags"><span class="risk-tag">滑点 ≤ ${percent(risk.maxSlippageBps)}</span><span class="risk-tag">冲击 ≤ ${percent(risk.maxPriceImpactBps)}</span><span class="risk-tag">保留双链 Gas</span></div></section></div>`;
  $('#refresh-market').addEventListener('click',event=>action(event.currentTarget,()=>api('/api/refresh',{method:'POST',body:{}}),'行情已刷新'));
  $('#engine-toggle').addEventListener('click',event=>action(event.currentTarget,()=>api('/api/engine/'+(e.running?'pause':'start'),{method:'POST',body:{}}),e.running?'自动执行已暂停':'自动执行监控已启动'));
  $('#execute-arbitrage').addEventListener('click',event=>action(event.currentTarget,()=>api('/api/engine/execute',{method:'POST',body:{}}),'执行任务已提交，请在档案中查看链上状态'));
