function field(label,name,value,{type='text',help='',min,max,step,scale,array=false,placeholder='',full=false}={}) {
  const attributes = `name="${name}" ${scale?`data-scale="${scale}"`:''} ${array?'data-array="true"':''} ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${step!==undefined?`step="${step}"`:''} placeholder="${escape(placeholder)}"`;
  const displayValue = array ? (value || []).join('\n') : scale ? numeric(value) / scale : value ?? '';
  return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label>${type==='textarea'?`<textarea id="f-${name}" ${attributes} rows="3">${escape(displayValue)}</textarea>`:`<input id="f-${name}" type="${type}" ${attributes} value="${escape(displayValue)}">`}${help?`<div class="help">${help}</div>`:''}</div>`;
}
function chainSettings(chain) {
  const c = state.config.chains[chain];
  return `<section class="card" id="settings-${chain}"><div class="card-header"><h2>${chainName(chain)} 配置</h2><span class="badge neutral">${chain==='bnb'?'Chain ID 56':'mainnet-beta'}</span></div><div class="card-body"><div class="form-grid">${field('代币合约 / Mint 地址',`chains.${chain}.tokenAddress`,c.tokenAddress,{help:'请独立核对两条链代币的发行方与跨链对应关系。',full:true})}${field('指定交易池地址',`chains.${chain}.poolAddress`,c.poolAddress,{help:'行情按指定池读取；执行路线仍需通过 OKX 与合约白名单校验。',full:true})}${field('代币精度',`chains.${chain}.tokenDecimals`,c.tokenDecimals,{type:'number',min:0,max:30,step:1})}${field('确认数',`chains.${chain}.confirmations`,c.confirmations,{type:'number',min:1,step:1})}${field('稳定币合约 / Mint',`chains.${chain}.stableAddress`,c.stableAddress,{full:true})}${field('稳定币精度',`chains.${chain}.stableDecimals`,c.stableDecimals,{type:'number',min:0,max:30,step:1})}${field(`${shortChain(chain)} 计价参考（USD）`,`chains.${chain}.nativeUsd`,c.nativeUsd,{type:'number',min:.000001,step:'any',help:'用于费用折美元与复核；请保持为当前参考价格。'})}${field('轮换 RPC（每行一个）',`chains.${chain}.rpcs`,c.rpcs,{type:'textarea',array:true,full:true,help:'按列表故障切换；仅使用你信任的 HTTPS RPC。'})}${field(chain==='bnb'?'允许的路由合约（每行一个）':'允许的 Solana 程序 ID（每行一个）',`chains.${chain}.${chain==='bnb'?'routerAllowlist':'programAllowlist'}`,c[chain==='bnb'?'routerAllowlist':'programAllowlist'] || [],{type:'textarea',array:true,full:true,help:'实盘签名前校验交易目标。请从服务官方来源核对后填写。'})}</div></div></section>`;
}
function walletStatusLabel(chain) {
  const w=state?.wallets?.[chain] || {};
  if(w.mode==='browser') return w.connected ? walletConnector.isConnectedHere(chain) ? '插件已连接' : '请在当前页重新连接' : '插件等待重新连接';
  if(w.mode==='private') return w.unlocked ? '本机签名已解锁' : '本机私钥已锁定';
  if(w.mode==='readonly') return '只读地址已保存';
  return '尚未连接钱包';
}
function walletSummary(chain) {
  const w=state.wallets?.[chain] || {},b=state.balances?.[chain] || {};
  const provider=w.mode==='browser'?walletConnector.providerName(w.provider):w.mode==='private'?'本机加密私钥':w.mode==='readonly'?'只读监控':'';
  const modeInfo=state.config.mode==='demo'?'<div class="help">当前为模拟模式，首页显示模拟余额；连接插件不会触发真实交易。</div>':w.address?b.error?`<div class="help negative">余额读取失败：${escape(b.error)}</div>`:b.address&&(chain==='bnb'?String(b.address).toLowerCase()===String(w.address).toLowerCase():String(b.address)===String(w.address))?`<div class="wallet-balance"><span>稳定币 ${usd(b.stableUsd,2)}</span><span>Gas ${number(b.nativeBalance,5)} ${shortChain(chain)}</span></div>`:'<div class="help">链上余额正在读取，请检查该链 RPC 配置。</div>':'';
  return `<div class="wallet-status"><span class="address">${escape(w.address || '尚未连接插件或导入地址')}</span></div><div class="help">${escape(provider)}${provider?' · ':''}${escape(walletStatusLabel(chain))}</div>${modeInfo}`;
}
function updateWalletPanels() {
  $$('[data-wallet-summary]').forEach(node=>{node.innerHTML=walletSummary(node.dataset.walletSummary);});
  $$('[data-wallet-state]').forEach(node=>{const chain=node.dataset.walletState,w=state.wallets?.[chain]||{};node.textContent=walletStatusLabel(chain);node.className='badge '+(w.canSign?'green':'neutral');});
  $$('[data-wallet-disconnect]').forEach(button=>{button.hidden=state.wallets?.[button.dataset.walletDisconnect]?.mode!=='browser';});
  $$('[data-wallet-restore]').forEach(button=>{const w=state.wallets?.[button.dataset.walletRestore]||{};button.hidden=!(w.mode==='browser'&&(w.hasLocalProfile||w.hasLocalWallet));});
}
function renderSigningBanner() {
  const node=$('#wallet-signing');if(!node)return;
  node.hidden=!walletSigning;if(!walletSigning)return;
  const provider=walletConnector.providerName(walletSigning.provider)||'插件钱包';
  node.innerHTML=`<span class="spinner"></span><div><strong>请在 ${escape(provider)} 中确认 ${chainName(walletSigning.chain)} 交易</strong><small>保持本页面打开。每一步确认后才会继续；取消或连接中断会暂停并记录。</small></div>`;
}
function walletCard(chain) {
  const wallet=state.wallets?.[chain]||{},providers=chain==='bnb'?['metamask','okx']:['phantom','okx'];
  return `<section class="card"><div class="card-header"><h3>${chainName(chain)} 钱包</h3><span class="badge ${wallet.canSign?'green':'neutral'}" data-wallet-state="${chain}">${escape(walletStatusLabel(chain))}</span></div><div class="card-body"><div data-wallet-summary="${chain}">${walletSummary(chain)}</div><div class="extension-wallet-buttons">${providers.map(name=>`<button type="button" class="button secondary" data-wallet-connect="${name}" data-chain="${chain}">连接 ${walletConnector.providerName(name)}</button>`).join('')}</div><div class="help">插件连接只申请公开地址。实盘交易会逐步弹出钱包确认；无人值守执行可使用下方本机加密私钥。</div><div class="form-actions"><button class="button text small" type="button" data-wallet-disconnect="${chain}" ${wallet.mode==='browser'?'':'hidden'}>断开插件连接</button><button class="button text small" type="button" data-wallet-restore="${chain}" ${wallet.mode==='browser'&&(wallet.hasLocalProfile||wallet.hasLocalWallet)?'':'hidden'}>恢复本机钱包</button></div><div class="wallet-method-divider"><span>或导入本机钱包</span></div><form class="wallet-form" data-chain="${chain}" autocomplete="off"><div class="toggle" role="group" aria-label="导入方式"><button type="button" class="active" data-wallet-mode="readonly">只读地址</button><button type="button" data-wallet-mode="private">加密私钥</button></div><input type="hidden" name="mode" value="readonly"><div class="field"><label>钱包地址</label><input name="address" placeholder="${chain==='bnb'?'0x…':'Solana 公钥地址'}" autocomplete="off" required></div><div class="field private-field" hidden><label>私钥</label><input type="password" name="secret" placeholder="${chain==='bnb'?'EVM 十六进制私钥':'Base58 私钥或 JSON 字节数组'}" autocomplete="new-password" spellcheck="false"><div class="help">只通过本机接口导入。保存后立即清空输入框，接口不会回显。</div></div><div class="field private-field" hidden><label>本机加密密码</label><input name="password" type="password" minlength="10" autocomplete="new-password" placeholder="至少 10 个字符"></div><button class="button secondary" type="submit">${icon('lock')}保存${chainName(chain)}钱包</button></form></div></section>`;
}
function renderSettings() {
  const c = state.config, r = c.risk, b = c.rebalance;
  $('#main').innerHTML = heading('CONFIGURATION','设置与钱包','链参数、执行边界与本机密钥，集中管理。')+
  `<div class="settings-nav"><a href="#settings-risk">执行与风控</a><a href="#settings-bnb">BNB Chain</a><a href="#settings-solana">Solana</a><a href="#settings-wallets">钱包管理</a><a href="#settings-okx">OKX API</a></div><form id="config-form" class="section-stack"><section class="card" id="settings-risk"><div class="card-header"><h2>执行与风控</h2><span class="badge ${c.mode==='demo'?'amber':'green'}">${c.mode==='demo'?'SIMULATION':'LIVE TRADING'}</span></div><div class="card-body"><div class="form-grid"><div class="field full"><label for="run-mode">运行模式</label><select name="mode" id="run-mode"><option value="demo" ${c.mode==='demo'?'selected':''}>模拟模式 · 不发送链上交易</option><option value="live" ${c.mode==='live'?'selected':''}>实盘模式 · 插件确认或本机签名</option></select><div class="help">切换实盘仅更改模式；需通过余额、路线、风控与钱包解锁检查后才会执行。</div></div><div class="field full"><label for="execution-mode">套利执行方式</label><select id="execution-mode" name="executionMode"><option value="bridge" ${c.executionMode!=='inventory'?'selected':''}>买入 → 跨链到账 → 卖出</option><option value="inventory" ${c.executionMode==='inventory'?'selected':''}>双侧库存 · 本轮不跨链</option></select><div class="help">库存模式使用高价链预先持有的同币；库存不足或单边失败时暂停。自动再平衡在库存模式下不执行。</div></div><div id="settings-inventory" class="field full" ${c.executionMode==='inventory'?'':'hidden'}>${field('当前同币标识（选填）','inventory.assetId',c.inventory?.assetId || '',{help:'用于单一已配置币对的档案归属；多币扫描在“同币机会”管理。'})}${field('当前币对的同币核验依据','inventory.mappingEvidence',c.inventory?.mappingEvidence || '',{type:'textarea',help:'填写已核对的发行方及两链1:1资产关系。地址、精度、池或标识变更后需重新核验；原已确认条目请先保存变更，再确认保存。'})}<label class="check-row"><input type="checkbox" name="inventory.mappingConfirmed" ${c.inventory?.mappingConfirmed?'checked':''}><span>我已核对当前两链地址、精度和池，确认是1:1的同一资产。</span></label><label class="check-row"><input type="checkbox" name="inventory.scanApprovedAssets" ${c.inventory?.scanApprovedAssets?'checked':''}><span>自动执行时使用“同币机会”中已核验的资产清单。</span></label><p class="help">保存设置不会启动交易。多币自动执行也受1–10U、利润、费用与累计额度限制。</p></div>${field('单笔套利金额（U）','risk.amountUsd',r.amountUsd,{type:'number',min:1,max:10,step:.01})}${field('最低预计净利润（U）','risk.minProfitUsd',r.minProfitUsd,{type:'number',step:.001,min:0})}${field('最大滑点（%）','risk.maxSlippageBps',r.maxSlippageBps,{type:'number',min:0,max:50,step:.01,scale:100})}${field('最大价格冲击（%）','risk.maxPriceImpactBps',r.maxPriceImpactBps,{type:'number',min:0,max:50,step:.01,scale:100})}${field('单次流程累计 BNB 费用上限（BNB）','risk.maxBnbGas',r.maxBnbGas,{type:'number',step:.000001,min:.000001})}${field('单次流程累计 SOL 费用上限（SOL）','risk.maxSolFee',r.maxSolFee,{type:'number',step:.000001,min:.000001})}${field('BNB 最低 Gas 储备','risk.reserveBnb',r.reserveBnb,{type:'number',step:.000001,min:0})}${field('SOL 最低 Gas 储备','risk.reserveSol',r.reserveSol,{type:'number',step:.000001,min:0})}${field('累计执行次数上限','risk.maxExecutions',r.maxExecutions,{type:'number',step:1,min:1})}${field('累计套利金额上限（U）','risk.maxCumulativeUsd',r.maxCumulativeUsd,{type:'number',step:.01,min:1})}${field('行情轮询间隔（秒）','pollIntervalMs',c.pollIntervalMs,{type:'number',step:1,min:1,scale:1000})}${field('行情最大有效期（秒）','risk.maxQuoteAgeMs',r.maxQuoteAgeMs,{type:'number',step:1,min:1,scale:1000})}${field('交易报价有效期（秒）','quoteTtlMs',c.quoteTtlMs,{type:'number',step:1,min:1,scale:1000})}</div></div></section>${chainSettings('bnb')}${chainSettings('solana')}<section class="card"><div class="card-header"><h2>自动再平衡</h2><span class="badge neutral">5U 触发 · 60 / 40</span></div><div class="card-body"><p class="section-intro">仅当一侧可用稳定币低于 5U 时触发，将不足一侧补到总资金的 60%，另一侧保留 40%。满足磨损与 Gas 储备检查后执行。</p><label class="check-row"><input type="checkbox" name="rebalance.enabled" ${b.enabled?'checked':''}><span>启用自动再平衡</span></label><p class="help" id="rebalance-mode-hint"></p><div class="form-grid section-gap">${field('跨链最大美元磨损（U）','rebalance.maxWearUsd',b.maxWearUsd,{type:'number',min:0,step:.01})}${field('跨链最大磨损率（%）','rebalance.maxWearBps',b.maxWearBps,{type:'number',min:0,max:100,step:.01,scale:100})}${field('再平衡冷却时间（分钟）','rebalance.cooldownMs',b.cooldownMs,{type:'number',min:1,step:1,scale:60000,help:'有跨链任务待确认时，禁止再次触发。'})}</div></div></section><div class="form-actions"><button type="submit" class="button">保存全部设置</button><span class="help">保存在本机；修改设置会先暂停自动执行。</span></div></form><div class="section-stack section-gap" id="settings-wallets"><section class="card"><div class="card-header"><h2>插件钱包与本机密钥</h2><button class="button secondary small" id="lock-vault">${icon('lock')}锁定密钥</button></div><div class="card-body"><p class="section-intro">BNB 与 Solana 分别连接插件或导入本机钱包。插件交易逐步确认；本机私钥用密码加密保存，重启后解锁。插件重新加载页面后需再次连接。</p><form id="unlock-form" class="inline-unlock" autocomplete="off"><input type="password" name="password" minlength="10" placeholder="输入本机加密密码" autocomplete="current-password" required aria-label="本机加密密码"><button type="submit" class="button secondary">解锁密钥</button></form></div></section><div class="wallet-grid">${walletCard('bnb')}${walletCard('solana')}</div><section class="card" id="settings-okx"><div class="card-header"><h2>OKX DEX API 凭证</h2><span class="badge neutral">本机加密存储</span></div><div class="card-body"><p class="section-intro">用于聚合报价、交易与跨链路线。凭证只在本机服务使用；已有凭证不会回显。</p><form id="okx-form" autocomplete="off"><div class="form-grid">${field('API Key','apiKey','',{type:'password',placeholder:'输入新的 API Key'})}${field('Secret Key','secretKey','',{type:'password',placeholder:'输入新的 Secret Key'})}${field('Passphrase','passphrase','',{type:'password',placeholder:'输入 API Passphrase'})}${field('本机加密密码','password','',{type:'password',placeholder:'至少 10 个字符'})}</div><div class="form-actions"><button type="submit" class="button secondary">加密保存 API 凭证</button></div></form><form id="project-form" class="section-gap"><div class="field"><label for="project-id">OKX Project ID（可选）</label><div class="field-row"><input id="project-id" name="projectId" value="${escape(c.okx?.projectId||'')}" placeholder="按 OKX 项目要求配置"><button type="submit" class="button secondary">保存</button></div></div></form></div></section></div>`;
  const executionModeInput=$('#execution-mode');
  const updateExecutionModeFields=()=>{const inventory=executionModeInput.value==='inventory';$('#settings-inventory').hidden=!inventory;const rebalance=$('#config-form [name=\"rebalance.enabled\"]');rebalance.disabled=inventory;$('#rebalance-mode-hint').textContent=inventory?'库存模式不执行自动跨链再平衡；此设置保留供跨链模式使用。':'';};
  executionModeInput.addEventListener('change',updateExecutionModeFields);updateExecutionModeFields();
  $('#config-form [name=\"inventory.assetId\"]')?.addEventListener('input',()=>{$('#config-form [name=\"inventory.mappingConfirmed\"]').checked=false;});
  for(const chain of chainKeys) for(const key of ['tokenAddress','tokenDecimals','poolAddress']) $('#config-form [name=\"chains.'+chain+'.'+key+'\"]')?.addEventListener('input',()=>{$('#config-form [name=\"inventory.mappingConfirmed\"]').checked=false;});
  $('#config-form').addEventListener('submit',saveConfig);
  $$('[data-wallet-connect]').forEach(button=>button.addEventListener('click',async()=>{const result=await action(button,()=>walletConnector.connect(button.dataset.chain,button.dataset.walletConnect),'插件钱包已连接；交易时请在钱包弹窗中确认');if(result&&tab==='settings')renderSettings();}));
  $$('[data-wallet-disconnect]').forEach(button=>button.addEventListener('click',async()=>{const result=await action(button,()=>walletConnector.disconnect(button.dataset.walletDisconnect),'插件连接已断开，自动执行已暂停');if(result&&tab==='settings')renderSettings();}));
  $$('[data-wallet-restore]').forEach(button=>button.addEventListener('click',async()=>{const chain=button.dataset.walletRestore;const result=await action(button,()=>api('/api/wallets/restore-local',{method:'POST',body:{chain}}),'已恢复原本机钱包');if(result){walletConnector.forget(chain);if(tab==='settings')renderSettings();}}));
  $$('.wallet-form').forEach(form=>{
    $$('[data-wallet-mode]',form).forEach(button=>button.addEventListener('click',()=>{
      const mode = button.dataset.walletMode; form.elements.mode.value = mode;
      $$('[data-wallet-mode]',form).forEach(b=>b.classList.toggle('active',b===button));
      $$('.private-field',form).forEach(el=>el.hidden=mode!=='private');
      form.elements.address.closest('.field').hidden=mode==='private';
      form.elements.address.required=mode==='readonly'; form.elements.secret.required=mode==='private'; form.elements.password.required=mode==='private';
      form.elements.secret.value='';form.elements.password.value='';
    }));
    form.addEventListener('submit',async event=>{
      event.preventDefault();const button=$('button[type=submit]',form), values=Object.fromEntries(new FormData(form));
      const body={chain:form.dataset.chain,mode:values.mode,...(values.mode==='private'?{secret:values.secret,password:values.password}:{address:values.address.trim()})};
      form.elements.secret.value='';form.elements.password.value='';
      const result=await action(button,()=>api('/api/wallets/import',{method:'POST',body}),'钱包已保存在本机');if(result){walletConnector.forget(form.dataset.chain);if(tab==='settings')renderSettings();}
    });
  });
  $('#unlock-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,password=form.elements.password.value;form.reset();const result=await action($('button',form),()=>api('/api/wallets/unlock',{method:'POST',body:{password}}),'密钥已解锁');if(result&&tab==='settings')renderSettings();});
  $('#lock-vault').addEventListener('click',async event=>{const result=await action(event.currentTarget,()=>api('/api/wallets/lock',{method:'POST',body:{}}),'密钥已锁定');if(result&&tab==='settings')renderSettings();});
  $('#okx-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,body=Object.fromEntries(new FormData(form));form.reset();await action($('button[type=submit]',form),()=>api('/api/okx/credentials',{method:'POST',body}),'OKX 凭证已加密保存在本机');});
  $('#project-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,config=structuredClone(state.config);config.okx={...config.okx,projectId:form.elements.projectId.value.trim()};await action($('button',form),()=>api('/api/config',{method:'POST',body:{config}}),'Project ID 已保存');});
}
async function saveConfig(event) {
  event.preventDefault();const form=event.currentTarget,config=structuredClone(state.config);
  $$('[name]',form).forEach(input=>{
    const path=input.name.split('.');let target=config;for(const key of path.slice(0,-1))target=target[key] ??= {};
    let value=input.type==='checkbox'?input.checked:input.dataset.array?input.value.split(/[\n,]+/).map(s=>s.trim()).filter(Boolean):input.type==='number'?Number(input.value)*(Number(input.dataset.scale)||1):input.value.trim();
    if(input.dataset.scale && input.type==='number') value=Math.round(value);
    target[path.at(-1)]=value;
  });
  const result=await action($('button[type=submit]',form),()=>api('/api/config',{method:'POST',body:{config}}),'全部设置已保存');if(result&&tab==='settings')renderSettings();
}

function renderBridge() {
  const b=state.config.rebalance, balances=state.balances || {}, bnb=numeric(balances.bnb?.stableUsd),sol=numeric(balances.solana?.stableUsd),total=bnb+sol;
  $('#main').innerHTML=heading('OKX CROSS-CHAIN','跨链资金工作台','BNB ⇄ Solana 聚合兑换与自动再平衡。',`<span class="badge ${b.enabled?'green':'neutral'}">自动再平衡${b.enabled?'已启用':'已关闭'}</span>`)+modeNotice()+`<div class="bridge-layout"><section class="card"><div class="card-header"><h2>手动跨链兑换</h2><span class="badge neutral">OKX DEX</span></div><div class="card-body"><form id="bridge-form" class="bridge-controls"><div class="bridge-chain-row"><div class="field bridge-chain-select"><label for="bridge-from">来源链</label><select id="bridge-from" name="fromChain"><option value="bnb">BNB Chain · USDT</option><option value="solana">Solana · USDC</option></select></div><button type="button" id="swap-direction" class="swap-direction" aria-label="交换跨链方向">⇄</button><div class="field bridge-chain-select"><label for="bridge-to">目标链</label><select id="bridge-to" name="toChain"><option value="solana">Solana · USDC</option><option value="bnb">BNB Chain · USDT</option></select></div></div><div><div class="field"><label for="bridge-amount">兑换金额</label><div class="amount-field"><input id="bridge-amount" name="amountUsd" type="number" step="any" min="0.000001" required placeholder="0.00"><span>U</span></div></div><div class="balance-line"><span>来源可用资金</span><span class="mono" id="bridge-available">${usd(bnb,2)}</span></div></div><div class="notice green compact-notice"><span class="notice-icon">⌁</span><p>单次与每日跨链金额不限。执行前检查美元磨损、磨损率、双链 Gas 储备与路线有效期。</p></div><button class="button" type="submit">获取跨链报价 ${icon('arrow')}</button></form></div></section><section class="card"><div class="card-header"><h2>路线与磨损预览</h2><span class="sub">先报价，再执行</span></div><div class="card-body" id="bridge-quote">${bridgeQuote?bridgeQuoteHtml():'<div class="quote-placeholder"><div class="quote-icon">⇄</div>输入金额，获取当前可用路线与完整费用。</div>'}</div></section></div><section class="card rebalance-layout"><div class="card-header"><h2>自动再平衡</h2><span class="badge ${b.enabled?'green':'neutral'}">${b.enabled?'监控中':'未启用'}</span></div><div class="card-body"><div class="detail-row"><span>双链可用稳定币总额</span><span class="mono">${usd(total,2)}</span></div><div class="rebalance-track" role="img" aria-label="BNB 资金比例 ${number(total?bnb/total*100:0,1)}%，Solana ${number(total?sol/total*100:0,1)}%"><i style="width:${total?bnb/total*100:50}%"></i></div><div class="rebalance-legend"><span>◇ BNB Chain <b class="mono">${usd(bnb,2)}</b></span><span>≋ Solana <b class="mono">${usd(sol,2)}</b></span></div><div class="form-grid three section-gap"><div><div class="stat-label">低余额触发阈值</div><div class="stat-value mono">&lt; $5.00</div></div><div><div class="stat-label">目标资金分配</div><div class="stat-value mono">60% / 40%</div></div><div><div class="stat-label">再平衡冷却</div><div class="stat-value mono">${number(numeric(b.cooldownMs)/60000,0)} 分钟</div></div></div><div class="rebalance-rule"><span class="positive">⌁</span><div><strong>补足低余额一侧，保留 Gas，避免重复跨链。</strong><p>预计磨损必须同时 ≤ ${usd(b.maxWearUsd,4)} 且 ≤ ${percent(b.maxWearBps)}。不足一侧补到 60%，另一侧保持 40%；跨链未完成或冷却中不重复触发。</p></div></div><div class="form-actions"><button class="button secondary small" data-tab="settings">调整再平衡设置</button></div></div></section>`;
  const form=$('#bridge-form');
  const directionChange=source=>{const from=form.elements.fromChain,to=form.elements.toChain;if(source===to)from.value=to.value==='bnb'?'solana':'bnb';else to.value=from.value==='bnb'?'solana':'bnb';$('#bridge-available').textContent=usd(state.balances?.[from.value]?.stableUsd,2);invalidateBridgeQuote();};
  form.elements.fromChain.addEventListener('change',()=>directionChange(form.elements.fromChain));form.elements.toChain.addEventListener('change',()=>directionChange(form.elements.toChain));
  form.elements.amountUsd.addEventListener('input',invalidateBridgeQuote);
  $('#swap-direction').addEventListener('click',()=>{const prior=form.elements.fromChain.value;form.elements.fromChain.value=form.elements.toChain.value;form.elements.toChain.value=prior;directionChange(form.elements.fromChain);});
  form.addEventListener('submit',async event=>{event.preventDefault();const revision=bridgeRevision,body={fromChain:form.elements.fromChain.value,toChain:form.elements.toChain.value,amountUsd:Number(form.elements.amountUsd.value)};const result=await action($('button[type=submit]',form),()=>api('/api/bridge/quote',{method:'POST',body}));if(result&&tab==='bridge'&&revision===bridgeRevision){bridgeQuote=result.amountUsd!==undefined?result:(result.quote || result);$('#bridge-quote').innerHTML=bridgeQuoteHtml();bindBridgeExecute();}});
  bindBridgeExecute();
}
