function bridgeQuoteHtml(){const q=bridgeQuote;return `<div class="direction">${chainPill(q.fromChain)}<em>→</em>${chainPill(q.toChain)}</div><div class="detail-list section-gap"><div class="detail-row"><span>兑换金额</span><span class="mono">${usd(q.amountUsd,4)}</span></div><div class="detail-row"><span>预计目标链到账</span><span class="mono positive">${usd(q.receivedUsd,4)}</span></div><div class="detail-row"><span>预计网络费</span><span class="mono">${usd(q.gasUsd,4)}</span></div><div class="detail-row"><span>美元磨损</span><span class="mono">${usd(q.wearUsd,4)}</span></div><div class="detail-row"><span>磨损率</span><span class="mono">${percent(q.wearBps)}</span></div><div class="detail-row"><span>报价有效至</span><span class="mono">${clockTime(q.expiresAt)}</span></div><div class="detail-row total"><span>Gas 储备</span><span class="mono">BNB ${number(state.config.risk.reserveBnb,4)} / SOL ${number(state.config.risk.reserveSol,4)}</span></div></div>${q.reasons?.length?`<div class="notice section-gap compact-notice"><p>${q.reasons.map(escape).join('<br>')}</p></div>`:''}<button class="button section-gap" id="bridge-execute" style="width:100%" ${!q.executable||state.engine?.busy?'disabled':''}>${state.config.mode==='demo'?'模拟执行跨链':'执行当前跨链路线'}${icon('arrow')}</button><div class="amount-note">报价变化或过期时，服务会阻止执行并要求重新报价。</div>`;}
