const estimatedProfit = t => t.estimate?.netProfitUsd ?? (Number.isFinite(t.estimate?.wearUsd) ? -t.estimate.wearUsd : undefined);
const actualProfit = t => t.actual?.cashSpreadProfitUsd ?? t.actual?.netProfitUsd ?? t.actual?.profitUsd ?? t.actualProfitUsd ?? t.reconciliation?.actualProfitUsd;
