function inventoryRecordHtml(t){if(!isInventoryTrade(t))return '';const deltas=t.actual?.inventoryDelta||{};return `<div class="notice blue section-gap"><p>本笔使用两侧预置库存。现金流价差未含未来补库存成本；两链库存尚未配平。</p></div><div class="detail-list section-gap">${chainKeys.filter(chain=>deltas[chain]).map(chain=>`<div class="detail-row"><span>${chainName(chain)} 代币库存变化（原始数量）</span><span class="mono break">${escape(deltas[chain].tokenRaw)} · 精度 ${escape(deltas[chain].decimals)}</span></div>`).join('')}${t.actual?.dustBuyRaw!==undefined?`<div class="detail-row"><span>换算余数（买入链原始数量）</span><span class="mono break">${escape(t.actual.dustBuyRaw)}</span></div>`:''}</div>`;}
const statusNames={CREATED:'已创建',NEEDS_REVIEW:'待人工核对',REVIEWED:'已人工核对',BUY_RECEIPT:'买入回执已获取',BRIDGE_RECEIPT:'跨链回执已获取',SELL_RECEIPT:'卖出回执已获取',QUOTED:'已报价',PREFLIGHT:'执行检查',BUY_SUBMITTING:'提交买入',BUY_SUBMITTED:'买入待确认',BUY_CONFIRMED:'买入已确认',BRIDGE_QUOTING:'跨链报价',BRIDGE_SUBMITTING:'提交跨链',BRIDGE_SUBMITTED:'跨链待确认',BRIDGE_CONFIRMED:'跨链已到账',SELL_QUOTING:'卖出报价',SELL_SUBMITTING:'提交卖出',SELL_SUBMITTED:'卖出待确认',SELL_CONFIRMED:'卖出已确认',RECONCILING:'复核中',COMPLETED:'已完成',COMPLETE:'已完成',FAILED:'失败已暂停',PAUSED:'已暂停',RECOVERY_REQUIRED:'需要人工核对',REJECTED:'检查未通过'};
function statusBadge(status){const key=String(status||'').toUpperCase();return `<span class="badge ${/COMPLETE/.test(key)?'green':/FAIL|PAUS|RECOVER|REJECT|NEEDS_REVIEW/.test(key)?'red':'neutral'}">${escape(statusNames[key] || status || '等待')}</span>`;}
